package envspec

import "encoding/json"

// Stream names. Payload JSON is frozen at these versions: fields are never
// renamed (golden tests pin every shape below). Schemas are generated by
// reflection inside the internal collectors that own each stream.
const (
	StreamHostMetrics    = "host.metrics@1"     // HostSnapshot
	StreamEnvResources   = "env.resources@1"    // ResourcesData
	StreamContainerLogs  = "container.logs@1"   // LogLine
	StreamEnvProcess     = "env.process@1"      // ProcessData
	StreamFSChanges      = "fs.changes@1"       // FSChange
	StreamFSObserve      = "fs.changes@2"       // FSStateEvent
	StreamFSActivity     = "fs.activity@1"      // FSActivityData
	StreamEnvHealth      = "env.health@1"       // HealthEvent
	StreamAndroidLogcat  = "android.logcat@1"   // LogLine
	StreamAndroidProc    = "android.proc@1"     // ProcEvent
	StreamAndroidPackage = "android.packages@1" // PackageEvent
	StreamAndroidCrash   = "android.crash@2"    // CrashEvent
	StreamAndroidState   = "android.state@1"    // StateEvent
	StreamAndroidMemory  = "android.memory@1"   // MemoryEvent
	StreamAndroidBinder  = "android.binder@1"   // BinderData
	StreamAndroidIPC     = "android.ipc@1"      // IPCEvent
	StreamAndroidFrida   = "android.frida@1"    // FridaData
	StreamNetPCAP        = "net.pcap"           // raw pcap bytes
	StreamNetPackets     = "net.packets@1"      // PacketData
	StreamNetFlows       = "net.flows@1"        // FlowData
	StreamNetDNS         = "net.dns@1"          // DNSData
	StreamNetTLS         = "net.tls@1"          // TLSData
	StreamNetHTTP        = "net.http@1"         // HTTPData
)

// ResourcesData is one env.resources@1 payload.
type ResourcesData struct {
	CPUPercent float64 `json:"cpu_percent"`
	MemMB      float64 `json:"mem_mb"`
	MemLimitMB float64 `json:"mem_limit_mb,omitempty"`
	NetRxKB    float64 `json:"net_rx_kb,omitempty"`
	NetTxKB    float64 `json:"net_tx_kb,omitempty"`
	Procs      int     `json:"procs,omitempty"`
	Top        string  `json:"top,omitempty"` // android guest top excerpt
}

// LogLine is a container.logs@1 / android.logcat@1 payload.
type LogLine struct {
	Text     string `json:"text"`
	Stream   string `json:"stream,omitempty"` // stdout/stderr (container)
	Tag      string `json:"tag,omitempty"`    // logcat
	Priority string `json:"priority,omitempty"`
	PID      int    `json:"pid,omitempty"`
	TID      int    `json:"tid,omitempty"`
}

// ProcessData is one env.process@1 payload: a chunk of an Exec/daemon
// stream (or its exit line), keyed by process ID.
type ProcessData struct {
	Proc   string `json:"proc"`
	Stream string `json:"stream"` // stdout, stderr, exit
	Text   string `json:"text"`
	Name   string `json:"name,omitempty"` // daemon name, when named
}

// FSChange is one fs.changes@1 payload.
type FSChange struct {
	Path   string `json:"path"`
	Change string `json:"change"` // created, modified, deleted
	Mode   int64  `json:"mode,omitempty"`
	Size   int64  `json:"size,omitempty"`
	Digest string `json:"digest,omitempty"`
	Root   string `json:"root,omitempty"`
}

// FSStateEvent is one fs.changes@2 payload for one watched root: a
// receipt-grade listing with inode/path identity and per-file digests. A
// cycle emits a snapshot when the listing changed, and an "unchanged"
// event naming the earlier snapshot's digest otherwise.
type FSStateEvent struct {
	Kind      string `json:"kind"` // "snapshot" | "unchanged" | "collector_error"
	Root      string `json:"root,omitempty"`
	BootID    string `json:"bootId,omitempty"`
	Error     string `json:"error,omitempty"`
	Format    string `json:"format,omitempty"`
	Command   string `json:"command,omitempty"`
	SHA256    string `json:"sha256,omitempty"`
	Bytes     []byte `json:"bytes,omitempty"`
	Truncated bool   `json:"truncated"`
	Baseline  bool   `json:"baseline"`
	ReadError string `json:"readError,omitempty"`
	Since     string `json:"since,omitempty"`
}

// FSStateParams are fs.changes@2's collector params.
type FSStateParams struct {
	Roots           []string `json:"roots"`
	IntervalSeconds int      `json:"interval_seconds,omitempty"`
}

// FSActivityData is one fs.activity@1 payload.
type FSActivityData struct {
	Path string `json:"path"`
	Op   string `json:"op"` // open, create, modify, delete, move, attrib
	Root string `json:"root,omitempty"`
}

// HealthEvent is one env.health@1 payload.
type HealthEvent struct {
	Component string `json:"component"`
	State     string `json:"state"`
	Detail    string `json:"detail,omitempty"`
	Capture   string `json:"capture,omitempty"`
}

// PacketData is one net.packets@1 summary.
type PacketData struct {
	Src     string `json:"src"`
	Dst     string `json:"dst"`
	Proto   string `json:"proto"`
	SrcPort uint16 `json:"sport,omitempty"`
	DstPort uint16 `json:"dport,omitempty"`
	Length  int    `json:"length"`
}

// FlowData is one net.flows@1 payload (windowed 5-tuple rollup).
type FlowData struct {
	Src       string `json:"src"`
	Dst       string `json:"dst"`
	Proto     string `json:"proto"`
	SrcPort   uint16 `json:"sport,omitempty"`
	DstPort   uint16 `json:"dport,omitempty"`
	Direction string `json:"direction"` // out, in (relative to smallest port side heuristic)
	Bytes     int64  `json:"bytes"`
	Packets   int64  `json:"packets"`
}

// DNSData is one net.dns@1 payload.
type DNSData struct {
	QName   string   `json:"qname"`
	QType   string   `json:"qtype,omitempty"`
	Answers []string `json:"answers,omitempty"`
	Server  string   `json:"server,omitempty"`
}

// TLSData is one net.tls@1 payload.
type TLSData struct {
	Server string `json:"server"`
	SNI    string `json:"sni,omitempty"`
	Port   uint16 `json:"port,omitempty"`
	JA4    string `json:"ja4,omitempty"` // best-effort fingerprint summary
}

// HTTPData is one net.http@1 payload.
type HTTPData struct {
	Method  string            `json:"method,omitempty"`
	Host    string            `json:"host,omitempty"`
	Path    string            `json:"path,omitempty"`
	Status  int               `json:"status,omitempty"`
	Server  string            `json:"server,omitempty"`
	Headers map[string]string `json:"headers,omitempty"`
	Dir     string            `json:"dir"` // request, response
}

// ProcEvent is one android.proc@1 payload.
type ProcEvent struct {
	Event   string `json:"event"` // start, exit
	PID     int    `json:"pid"`
	Name    string `json:"name"`
	Package string `json:"package,omitempty"`
}

// PackageEvent is one android.packages@1 payload.
type PackageEvent struct {
	Event   string `json:"event"` // installed, removed
	Package string `json:"package"`
}

// BinderData is one android.binder@1 payload (metadata only, no payload).
type BinderData struct {
	PID    int    `json:"pid"`
	TID    int    `json:"tid,omitempty"`
	Target string `json:"target,omitempty"`
	Code   uint32 `json:"code,omitempty"`
	Flags  uint32 `json:"flags,omitempty"`
	Reply  bool   `json:"reply,omitempty"`
	Raw    string `json:"raw,omitempty"`
}

// CrashEvent is one android.crash@2 payload. Crashes are always reported
// and never acted on.
type CrashEvent struct {
	Kind      string         `json:"kind"` // "crash" | "anr" (crash buffer lines) | "tombstone" | "collector_error"
	Process   string         `json:"process,omitempty"`
	PID       int            `json:"pid,omitempty"`
	Signal    string         `json:"signal,omitempty"`
	Text      string         `json:"text,omitempty"`
	BootID    string         `json:"bootId,omitempty"`    // /proc/sys/kernel/random/boot_id read in the same poll cycle; empty if unreadable
	Error     string         `json:"error,omitempty"`     // collector_error: what failed (list/permission/boot id), verbatim
	Tombstone *TombstoneFile `json:"tombstone,omitempty"` // kind == "tombstone"
}

// TombstoneFile is one tombstone acquisition: device-reported metadata, the
// exact bytes read, and the installed code identity of the crashing package
// at detection time.
type TombstoneFile struct {
	Path              string `json:"path"`                        // e.g. /data/tombstones/tombstone_03
	Size              int64  `json:"size"`                        // device-reported size (stat), -1 if unknown
	MTime             int64  `json:"mtime"`                       // device-reported mtime, unix seconds, 0 if unknown
	SHA256            string `json:"sha256,omitempty"`            // lowercase hex over Bytes exactly as retained
	Bytes             []byte `json:"bytes,omitempty"`             // exact raw file bytes (base64 in JSON); omitted for preexisting and on read error
	Truncated         bool   `json:"truncated"`                   // Bytes is only a prefix: the file exceeded the collector's retention cap
	Preexisting       bool   `json:"preexisting"`                 // already present (same path+size+mtime) when the collector started; metadata only
	ReadError         string `json:"readError,omitempty"`         // read failed (exit status / stderr); Bytes empty
	Package           string `json:"package,omitempty"`           // package of the crashing process (Process with any ":suffix" stripped)
	PackageCodePath   string `json:"packageCodePath,omitempty"`   // from `pm path <package>` (base.apk) at detection time
	PackageCodeSHA256 string `json:"packageCodeSha256,omitempty"` // lowercase hex sha256 of that base.apk (device-side sha256sum, as root)
	PackageCodeError  string `json:"packageCodeError,omitempty"`  // why the installed code identity could not be resolved
}

// State parts: what one android.state@1 snapshot reads.
const (
	StatePartStorage   = "storage"    // the package's private storage, listed as root
	StatePartPackage   = "package"    // `dumpsys package <pkg>`: uid, permissions, grant flags, declared permissions
	StatePartAppOps    = "appops"     // `appops get <pkg>`: package and uid AppOps modes
	StatePartURIGrants = "uri-grants" // `dumpsys activity -a permissions`: the device-wide URI grant table
)

// Snapshot formats: how a snapshot's Bytes are to be read.
const (
	StorageFormat   = "craggy.android-storage@1" // the collector's own listing
	PackageFormat   = "dumpsys-package"
	AppOpsFormat    = "appops-get"
	URIGrantsFormat = "dumpsys-activity-permissions"
)

// StateEvent is one android.state@1 payload. A part is read every cycle.
// Its first read since the collector started, and every read whose content
// or package identity differs from the last one emitted, is a "snapshot"
// carrying the exact bytes and their digest; an identical read is an
// "unchanged" event naming the digest of that earlier snapshot, so any
// capture window holds the state at its edges. Read failures are snapshots
// with ReadError, never empty content; failures outside a part are
// collector_error events.
type StateEvent struct {
	Kind    string `json:"kind"`              // "snapshot" | "unchanged" | "collector_error"
	Part    string `json:"part,omitempty"`    // storage | package | appops | uri-grants
	Package string `json:"package,omitempty"` // empty for the device-wide uri-grants part
	BootID  string `json:"bootId,omitempty"`  // /proc/sys/kernel/random/boot_id read in the same cycle; empty if unreadable
	Error   string `json:"error,omitempty"`   // collector_error: what failed, verbatim

	Format    string `json:"format,omitempty"`    // how Bytes are read (StorageFormat, PackageFormat, ...)
	Command   string `json:"command,omitempty"`   // the device command the part ran
	SHA256    string `json:"sha256,omitempty"`    // lowercase hex over Bytes exactly as retained (unchanged: of the earlier snapshot)
	Bytes     []byte `json:"bytes,omitempty"`     // exact retained bytes (base64 in JSON); snapshot only
	Truncated bool   `json:"truncated"`           // Bytes is only a prefix (retention or entry cap reached)
	Baseline  bool   `json:"baseline"`            // the part's first read since the collector started
	ReadError string `json:"readError,omitempty"` // the part could not be read (exit status / stderr); Bytes empty
	Since     string `json:"since,omitempty"`     // unchanged: time of the snapshot it repeats (RFC 3339)

	// Package identity at the read, for package-scoped parts.
	UID        int    `json:"uid,omitempty"`        // app uid from `pm list packages -U` (0: unresolved)
	CodePath   string `json:"codePath,omitempty"`   // installed base.apk from `pm path`
	CodeSHA256 string `json:"codeSha256,omitempty"` // lowercase hex sha256 of that base.apk (device-side, as root)
	CodeError  string `json:"codeError,omitempty"`  // why the uid or installed code could not be resolved
}

// StateParams are android.state@1's collector params.
type StateParams struct {
	Packages        []string `json:"packages"`
	Parts           []string `json:"parts,omitempty"`
	IntervalSeconds int      `json:"interval_seconds,omitempty"`
}

// MemoryEvent is one android.memory@1 payload. Each cycle resolves the
// package's main process, then emits one "maps" part holding the exact
// /proc/<pid>/maps bytes and one "mapping" part per readable private
// mapping holding the mapping's first retained bytes. A part whose content
// is identical to its last snapshot for the same process instance is an
// "unchanged" event naming the digest. Read failures are snapshots with
// ReadError, never empty content; failures outside a part are
// collector_error events. The collector only ever reads memory.
type MemoryEvent struct {
	Kind    string `json:"kind"`              // "snapshot" | "unchanged" | "collector_error"
	Part    string `json:"part,omitempty"`    // maps | mapping
	Package string `json:"package,omitempty"` // the watched package
	BootID  string `json:"bootId,omitempty"`  // boot id read in the same cycle; empty if unreadable
	Error   string `json:"error,omitempty"`   // collector_error: what failed, verbatim

	PID   int    `json:"pid,omitempty"`   // the package's main process this cycle (0: absent)
	Start string `json:"start,omitempty"` // /proc/<pid>/stat starttime; process-instance identity

	Address   uint64 `json:"address,omitempty"`   // mapping: first retained address (mapping begin)
	End       uint64 `json:"end,omitempty"`       // mapping: mapping end address
	Perms     string `json:"perms,omitempty"`     // mapping: maps permission string, e.g. rw-p
	Offset    uint64 `json:"offset,omitempty"`    // mapping: file offset from maps
	Path      string `json:"path,omitempty"`      // mapping: maps pathname ("[heap]", "" when anonymous)
	SHA256    string `json:"sha256,omitempty"`    // lowercase hex over Bytes exactly as retained
	Bytes     []byte `json:"bytes,omitempty"`     // exact retained bytes (base64 in JSON); snapshot only
	Truncated bool   `json:"truncated"`           // Bytes covers only a prefix of the mapping (or maps)
	Baseline  bool   `json:"baseline"`            // first read of this part for this process instance
	ReadError string `json:"readError,omitempty"` // the part could not be read; Bytes empty
	Since     string `json:"since,omitempty"`     // unchanged: time of the snapshot it repeats (RFC 3339)

	// maps part only: how many readable private mappings were not read this
	// cycle because a configured cap was reached. Consumers must treat
	// cells in unread mappings as unobserved, never as unchanged.
	OmittedMappings int `json:"omittedMappings,omitempty"`
}

// MemoryParams are android.memory@1's collector params.
type MemoryParams struct {
	Package             string `json:"package"`
	IntervalSeconds     int    `json:"interval_seconds,omitempty"`
	MaxMappingBytes     int    `json:"max_mapping_bytes,omitempty"`
	MaxTotalBytes       int    `json:"max_total_bytes,omitempty"`
	MappingPathContains string `json:"mapping_path_contains,omitempty"`
}

// IPC dispatch kinds observed on android.ipc@1.
const (
	IPCActivity  = "activity"
	IPCService   = "service"
	IPCBroadcast = "broadcast"
)

// IPCEvent is one android.ipc@1 payload: one observed intent dispatch with
// caller and resolved target.
type IPCEvent struct {
	Kind       string `json:"kind"`
	CallerUID  int    `json:"callerUid,omitempty"`  // "from uid N", when logged (-1: not recorded)
	Component  string `json:"component,omitempty"`  // resolved cmp=pkg/.Comp
	Action     string `json:"action,omitempty"`     // act=
	Data       string `json:"data,omitempty"`       // dat=
	Type       string `json:"type,omitempty"`       // typ=
	Flags      string `json:"flags,omitempty"`      // flg=0x...
	GrantRead  bool   `json:"grantRead,omitempty"`  // FLAG_GRANT_READ_URI_PERMISSION (0x1)
	GrantWrite bool   `json:"grantWrite,omitempty"` // FLAG_GRANT_WRITE_URI_PERMISSION (0x2)
	Raw        string `json:"raw"`
}

// FridaData kinds whose arrival has protocol meaning for observers: a
// checkpoint round-trip completed, and the script reporting itself ready.
const (
	FridaCheckpoint = "checkpoint"
	FridaReady      = "loaded"
)

// FridaData is one android.frida@1 payload (a script send() or log line).
type FridaData struct {
	Package        string          `json:"package,omitempty"`
	Process        string          `json:"process,omitempty"`
	Kind           string          `json:"kind,omitempty"`
	PID            int             `json:"pid,omitempty"`
	ScriptSHA256   string          `json:"scriptSha256,omitempty"`
	RuntimeVersion string          `json:"runtimeVersion,omitempty"`
	BridgeSHA256   string          `json:"bridgeSha256,omitempty"`
	Data           []byte          `json:"data,omitempty"`
	Error          string          `json:"error,omitempty"`
	Level          string          `json:"level,omitempty"`
	Payload        json.RawMessage `json:"payload,omitempty"`
	Log            string          `json:"log,omitempty"`
	// Checkpoint times are sampled by the host SDK around its RPC, not by
	// the instrumented process. Payload is the script's checkpoint result.
	RequestedAt string `json:"requestedAt,omitempty"`
	CompletedAt string `json:"completedAt,omitempty"`
}

// FridaParams are android.frida@1's collector params. Exactly one of
// Package or Process names the target; Spawn requires Package.
type FridaParams struct {
	Script               string `json:"script"`
	Package              string `json:"package"`
	Process              string `json:"process,omitempty"`
	Spawn                bool   `json:"spawn"`
	Port                 int    `json:"port"`
	CheckpointIntervalMS int    `json:"checkpoint_interval_ms,omitempty"`
}
